// ===============================
// DECRYPT TOPIC (AES-256-CBC)
// ===============================

const algorithm = "aes-256-cbc";
const sharedSecret = env.get("TOPIC_AES_SECRET");

if (!sharedSecret || sharedSecret.length < 16) {
    node.error("TOPIC_AES_SECRET non configurato o troppo corto");
    return null;
}

const parts = String(msg.topic || "").split("/");

if (parts.length !== 3 || parts[0] !== "enc") {
    return null;
}

const ivHex = parts[1];
const encryptedHex = parts[2];

if (!/^[0-9a-fA-F]{32}$/.test(ivHex) || !/^[0-9a-fA-F]+$/.test(encryptedHex)) {
    node.warn("Topic cifrato non valido");
    return null;
}

const key = crypto.createHash("sha256")
                  .update(sharedSecret)
                  .digest();

const iv = Buffer.from(ivHex, "hex");

try {
    const decipher = crypto.createDecipheriv(algorithm, key, iv);
    let decrypted = decipher.update(encryptedHex, "hex", "utf8");
    decrypted += decipher.final("utf8");
    msg.topic = decrypted;
    return msg;
} catch (err) {
    node.error("Errore decrypt topic: " + err.message);
    return null;
}

msg.payload = msg.payload || {};
msg.payload.tracing = msg.payload.tracing || {};
msg.payload.tracing.data_ctrl_recv = Date.now();

return msg;

msg.payload = msg.payload || {};
msg.payload.tracing = msg.payload.tracing || {};
msg.payload.tracing.data_ctrl_send = Date.now();

return msg;

const metadata =
    msg.payload?.metadata ||
    msg.payload?.encrypted?.metadata ||
    {};

const messageId = metadata.message_id;

if (!messageId) {
    node.warn("message_id mancante: record non correlabile");
    return null;
}

let ts = Number(metadata.timestamp_acq);

if (!Number.isFinite(ts)) {
    ts = Date.now();
    node.warn("timestamp_acq mancante: uso timestamp di fallback");
}

msg.payload = {
    message_id: messageId,
    topic: msg.topic,
    payload: msg.payload,
    ts: ts
};

return msg;

let records = msg.payload;

let values = [];
let params = [];
let i = 1;

for (let r of records) {

    let p = r.payload.encrypted || r.payload;
    let tracing = r.payload.tracing || {};

    values.push(`($${i},$${i + 1},$${i + 2},to_timestamp($${i + 3}/1000.0),$${i + 4},$${i + 5},$${i + 6})`);

    params.push(
        r.message_id,
        r.topic,
        Buffer.from(p.encrypted_data, "hex"),
        r.ts,
        tracing.data_acq_send || null,
        tracing.data_ctrl_recv || null,
        tracing.data_ctrl_send || null
    );

    i += 7;
}

msg.query = `
INSERT INTO sensor_data
(message_id, topic, encrypted_data, ts,
 data_acq_send, data_ctrl_recv, data_ctrl_send)
VALUES ${values.join(",")}
`;

msg.params = params;

return msg;

// =============================
// NORMALIZE PROC UPDATE
// =============================

if (!msg.payload || !msg.payload.message_id || msg.payload.data_proc_recv == null) {
    return null;
}

msg.payload = {
    message_id: String(msg.payload.message_id),
    data_proc_recv: Number(msg.payload.data_proc_recv)
};

return msg;

// =============================
// PREPARE PROC UPDATE BATCH
// CORRELAZIONE SU MESSAGE_ID
// =============================

let records = msg.payload;

if (!Array.isArray(records) || records.length === 0) {
    return null;
}

records = records.filter(r =>
    r &&
    typeof r.message_id === "string" &&
    r.message_id.trim() !== "" &&
    r.data_proc_recv !== undefined &&
    r.data_proc_recv !== null
);

if (records.length === 0) {
    return null;
}

let latestByMessageId = {};

for (let r of records) {
    latestByMessageId[r.message_id] = Number(r.data_proc_recv);
}

let entries = Object.entries(latestByMessageId);

if (entries.length === 0) {
    return null;
}

let values = [];
let params = [];
let i = 1;

for (let [messageId, procRecv] of entries) {
    values.push(`($${i}::text, $${i + 1}::bigint)`);
    params.push(messageId, procRecv);
    i += 2;
}

msg.query = `
WITH incoming(message_id, data_proc_recv) AS (
    VALUES ${values.join(",")}
)
UPDATE sensor_data s
SET data_proc_recv = i.data_proc_recv
FROM incoming i
WHERE s.message_id = i.message_id;
`;

msg.params = params;

return msg;

msg.query = `
DROP TABLE IF EXISTS sensor_data CASCADE;

CREATE TABLE IF NOT EXISTS sensor_data (

    id BIGSERIAL PRIMARY KEY,
    message_id TEXT NOT NULL UNIQUE,
    topic TEXT NOT NULL,
    encrypted_data BYTEA NOT NULL,
    ts TIMESTAMPTZ DEFAULT NOW(),

    data_acq_send BIGINT,
    data_ctrl_recv BIGINT,
    data_ctrl_send BIGINT,
    data_proc_recv BIGINT

);

CREATE UNIQUE INDEX IF NOT EXISTS idx_sensor_message_id
ON sensor_data(message_id);

CREATE INDEX IF NOT EXISTS idx_sensor_ts
ON sensor_data(ts DESC);

CREATE INDEX IF NOT EXISTS idx_sensor_topic_ts
ON sensor_data(topic, ts DESC);

`;

return msg;

