const dashboardSecret = env.get("DASHBOARD_AUTH_SECRET");

if (!dashboardSecret || dashboardSecret.length < 16) {
    node.error("DASHBOARD_AUTH_SECRET non configurato o troppo corto");
    return null;
}

function sqlLiteral(value) {
    return "'" + String(value).replace(/'/g, "''") + "'";
}

const pepperSql = sqlLiteral(dashboardSecret);

msg.query = `
DROP TABLE IF EXISTS dashboard_users CASCADE;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE dashboard_users (

    id SERIAL PRIMARY KEY,

    username TEXT NOT NULL UNIQUE,
    role TEXT NOT NULL CHECK (role IN ('user','admin','guest')),
    password_hash TEXT NOT NULL,
    active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()

);

CREATE INDEX IF NOT EXISTS idx_dashboard_users_username
ON dashboard_users(username);

INSERT INTO dashboard_users (username, role, password_hash, active, updated_at)
VALUES
('user','user',crypt('user_iot_2026' || ${pepperSql}, gen_salt('bf')),true,NOW()),
('admin','admin',crypt('admin_iot_2026' || ${pepperSql}, gen_salt('bf')),true,NOW()),
('guest','guest',crypt('guest_iot_2026' || ${pepperSql}, gen_salt('bf')),true,NOW());
`;

return msg;

